#!/usr/bin/env python3
# Autonomously generated by an AI agent.
import argparse
import hashlib
import json
import math
from pathlib import Path
import sys
from time import perf_counter

PROTOCOL_VERSION = 2
MAX_REQUEST_BYTES = 64 * 1024


def report_progress(value):
    print(f"MIXXX_BEAT_THIS_PROGRESS {value:.6f}", file=sys.stderr, flush=True)


def peak_rss_bytes():
    try:
        import resource
    except ImportError:
        return None
    usage = resource.getrusage(resource.RUSAGE_SELF).ru_maxrss
    return int(usage if sys.platform == "darwin" else usage * 1024)


def predict_with_progress(tracker, signal, sample_rate, progress, timings):
    from beat_this.inference import split_piece

    started = perf_counter()
    spect = tracker.signal2spect(signal, sample_rate)
    progress(0.2)
    chunks, _ = split_piece(spect, 1500, border_size=6, avoid_short_end=True)
    total = len(chunks)
    del chunks
    timings["preprocessing_seconds"] = perf_counter() - started
    completed = 0

    def chunk_completed(_module, _inputs, _output):
        nonlocal completed
        completed += 1
        progress(0.2 + 0.75 * min(completed / total, 1))

    hook = tracker.model.register_forward_hook(chunk_completed)
    started = perf_counter()
    try:
        beat_logits, downbeat_logits = tracker.spect2frames(spect)
    finally:
        hook.remove()
    timings["inference_seconds"] = perf_counter() - started
    started = perf_counter()
    result = tracker.frames2beats(beat_logits, downbeat_logits)
    timings["postprocessing_seconds"] = perf_counter() - started
    progress(0.98)
    return result


def verify_checkpoint(path, expected_sha256):
    checkpoint = Path(path)
    if not checkpoint.is_file():
        raise ValueError("Model checkpoint does not exist")
    expected = expected_sha256.lower()
    if len(expected) != 64 or any(
        c not in "0123456789abcdef" for c in expected
    ):
        raise ValueError("A valid model SHA-256 is required")
    with checkpoint.open("rb") as stream:
        digest = hashlib.sha256()
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
        actual = digest.hexdigest()
    if actual != expected:
        raise ValueError("Model checkpoint SHA-256 mismatch")
    return checkpoint


def validate_positions(values, duration):
    result = [float(value) for value in values]
    if any(
        not math.isfinite(value) or value < 0 or value > duration + 0.04
        for value in result
    ):
        raise ValueError("Model returned an out-of-range timestamp")
    if any(a >= b for a, b in zip(result, result[1:])):
        raise ValueError("Model timestamps are not strictly increasing")
    # Centered STFT padding can produce a prediction at the end boundary.
    # Discard at most two 50 Hz prediction frames outside the actual audio.
    return [value for value in result if value < duration]


def checkpoint_identity(path):
    stat = Path(path).stat()
    return (
        stat.st_dev,
        stat.st_ino,
        stat.st_size,
        stat.st_mtime_ns,
        stat.st_ctime_ns,
    )


class CheckpointChangedError(RuntimeError):
    pass


class BeatThisRuntime:
    def __init__(self, checkpoint, sha256, progress=report_progress):
        started = perf_counter()
        before = checkpoint_identity(checkpoint)
        self.checkpoint = verify_checkpoint(checkpoint, sha256)
        self.identity = checkpoint_identity(self.checkpoint)
        if before != self.identity:
            raise CheckpointChangedError(
                "Checkpoint changed during verification"
            )
        self.sha256 = sha256.lower()
        self.startup_timings = {
            "verify_checkpoint_seconds": perf_counter() - started,
        }
        progress(0.01)
        imported = perf_counter()
        from importlib.metadata import version

        if version("beat-this") != "1.1.0":
            raise ValueError("This backend requires beat-this 1.1.0")
        import numpy as np
        import torch
        from beat_this.inference import Audio2Beats

        self.np = np
        self.torch = torch
        self.startup_timings["imports_seconds"] = perf_counter() - imported
        progress(0.05)
        torch.set_num_threads(2)
        torch.set_num_interop_threads(1)
        loaded = perf_counter()
        with torch.inference_mode():
            self.tracker = Audio2Beats(
                checkpoint_path=str(self.checkpoint), device="cpu", dbn=False
            )
        self.startup_timings["model_load_seconds"] = perf_counter() - loaded
        self.check_identity()
        self.startup_timings["startup_seconds"] = perf_counter() - started
        progress(0.1)

    def check_identity(self):
        try:
            unchanged = checkpoint_identity(self.checkpoint) == self.identity
        except OSError:
            unchanged = False
        if not unchanged:
            raise CheckpointChangedError(
                "Checkpoint changed; restart the worker"
            )

    def analyze(
        self, audio, sample_rate, frames=None, progress=report_progress
    ):
        started = perf_counter()
        self.check_identity()
        if type(sample_rate) is not int or not 8000 <= sample_rate <= 192000:
            raise ValueError("Unsupported sample rate")
        audio_path = Path(audio)
        if not audio_path.is_file() or audio_path.stat().st_size % 4:
            raise ValueError("Invalid native float32 mono audio file")
        if frames is not None and (
            type(frames) is not int
            or frames <= 0
            or audio_path.stat().st_size != frames * 4
        ):
            raise ValueError("Audio frame count mismatch")
        signal = self.np.memmap(audio_path, dtype=self.np.float32, mode="r")
        try:
            if signal.size == 0 or not self.np.isfinite(signal).all():
                raise ValueError("Empty or non-finite audio")
            duration = len(signal) / sample_rate
            timings = {"audio_validation_seconds": perf_counter() - started}
            progress(0.1)
            with self.torch.inference_mode():
                beats, downbeats = predict_with_progress(
                    self.tracker, signal, sample_rate, progress, timings
                )
            validated = perf_counter()
            beats = validate_positions(beats, duration)
            downbeats = validate_positions(downbeats, duration)
            beat_set = set(beats)
            if any(beat not in beat_set for beat in downbeats):
                raise ValueError("Downbeats must be a subset of beats")
            timings["postprocessing_seconds"] += perf_counter() - validated
            self.check_identity()
            timings["job_seconds"] = perf_counter() - started
            progress(1.0)
            return {
                "version": 1,
                "model_sha256": self.sha256,
                "beats": beats,
                "downbeats": downbeats,
            }, timings
        finally:
            signal._mmap.close()


def analyze(args):
    runtime = BeatThisRuntime(args.checkpoint, args.sha256)
    result, timings = runtime.analyze(args.audio, args.sample_rate)
    if getattr(args, "timings", False):
        result["timings"] = {**runtime.startup_timings, **timings}
        result["peak_rss_bytes"] = peak_rss_bytes()
    return result


def json_line(output, value):
    output.write(
        json.dumps(value, allow_nan=False, separators=(",", ":")) + "\n"
    )
    output.flush()


def serve(args, input_stream=None, output_stream=None, runtime_factory=None):
    if input_stream is None and hasattr(sys.stdin, "reconfigure"):
        sys.stdin.reconfigure(encoding="utf-8", errors="strict")
    if output_stream is None and hasattr(sys.stdout, "reconfigure"):
        sys.stdout.reconfigure(encoding="utf-8", errors="strict")
    input_stream = input_stream if input_stream is not None else sys.stdin
    output_stream = output_stream if output_stream is not None else sys.stdout
    factory = (
        runtime_factory if runtime_factory is not None else BeatThisRuntime
    )

    def emit(kind, **fields):
        json_line(
            output_stream,
            {"protocol": PROTOCOL_VERSION, "type": kind, **fields},
        )

    last_startup_progress = 0.0

    def startup_progress(value):
        nonlocal last_startup_progress
        if (
            type(value) not in (int, float)
            or not last_startup_progress <= value <= 0.1
            or not math.isfinite(value)
        ):
            raise ValueError("Invalid startup progress")
        last_startup_progress = value
        emit("startup_progress", progress=value)

    runtime = factory(args.checkpoint, args.sha256, progress=startup_progress)

    emit(
        "ready",
        model_sha256=runtime.sha256,
        timings=runtime.startup_timings,
        peak_rss_bytes=peak_rss_bytes(),
    )
    used_ids = set()
    while True:
        line = input_stream.readline(MAX_REQUEST_BYTES + 1)
        if not line:
            return 0
        if len(line.encode("utf-8")) > MAX_REQUEST_BYTES:
            emit("error", id="", error="Request exceeds 64 KiB", fatal=True)
            return 1
        identifier = ""
        try:
            request = json.loads(line)
            if not isinstance(request, dict):
                raise ValueError("Request must be an object")
            value = request.get("id")
            if isinstance(value, str) and 0 < len(value) <= 128:
                identifier = value
            if (
                type(request.get("protocol")) is not int
                or request["protocol"] != PROTOCOL_VERSION
            ):
                raise ValueError("Unsupported worker protocol")
            if request.get("type") == "shutdown":
                return 0
            if request.get("type") != "analyze":
                raise ValueError("Unsupported request type")
            if not identifier or any(ord(char) < 32 for char in identifier):
                raise ValueError("Invalid request id")
            if identifier in used_ids:
                raise ValueError("Duplicate request id")
            used_ids.add(identifier)
            if (
                not isinstance(request.get("audio"), str)
                or not Path(request["audio"]).is_absolute()
            ):
                raise ValueError("Audio path must be absolute")
            if (
                type(request.get("frames")) is not int
                or request["frames"] <= 0
            ):
                raise ValueError("A positive audio frame count is required")
            if (
                type(request.get("sample_rate")) is not int
                or not 8000 <= request["sample_rate"] <= 192000
            ):
                raise ValueError("Unsupported sample rate")
            last_progress = 0.0

            def progress(value):
                nonlocal last_progress
                if not math.isfinite(value) or not last_progress <= value <= 1:
                    raise ValueError("Invalid model progress")
                last_progress = value
                emit("progress", id=identifier, progress=value)

            result, timings = runtime.analyze(
                request["audio"],
                request["sample_rate"],
                request["frames"],
                progress,
            )
            emit(
                "result",
                id=identifier,
                result=result,
                timings=timings,
                peak_rss_bytes=peak_rss_bytes(),
            )
        except CheckpointChangedError as error:
            emit("error", id=identifier, error=str(error), fatal=True)
            return 1
        except Exception as error:
            emit("error", id=identifier, error=str(error))


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument("--serve", action="store_true")
    parser.add_argument("--audio")
    parser.add_argument("--sample-rate", type=int)
    parser.add_argument("--checkpoint", required=True)
    parser.add_argument("--sha256", required=True)
    parser.add_argument("--timings", action="store_true")
    args = parser.parse_args()
    if args.serve and (args.audio is not None or args.sample_rate is not None):
        parser.error("--serve does not accept --audio or --sample-rate")
    if not args.serve and (args.audio is None or args.sample_rate is None):
        parser.error("--audio and --sample-rate are required without --serve")
    try:
        if args.serve:
            return serve(args)
        result = analyze(args)
    except Exception as error:
        print(f"Beat This! analysis failed: {error}", file=sys.stderr)
        return 1
    json.dump(result, sys.stdout, allow_nan=False, separators=(",", ":"))
    return 0


if __name__ == "__main__":
    sys.exit(main())
# End of autonomously generated text.
